function routeRequest(request, registry) {
  const claims = verifySSO(request.token);
  const server = registry.servers.find((s) => s.id === request.targetServerId);
  if (!server) throw new Error('unknown target server, reject');

  if (!server.allowedTeams.includes(claims.team)) {
    auditLog.write({ userId: claims.userId, team: claims.team, target: server.id, result: 'denied' });
    throw new Error('team not permitted to call this server');
  }

  auditLog.write({ userId: claims.userId, team: claims.team, target: server.id, result: 'allowed' });
  return forwardTo(server.address, request);
}
